    @Override public void onCreate(Bundle state){super.onCreate(state);prefs=new ru.funpay.tools.Settings(this);if(state!=null){page=state.getString("page","home");chatId=state.getString("chatId","");chatName=state.getString("chatName","");for(String key:state.keySet())if(key.startsWith("draft_"))drafts.put(key.substring(6),state.getString(key,""));}render();handler.post(refreshStatus);AppUpdates.check(this,false);}
