    String actionIcon(String label){label=label.toLowerCase(Locale.ROOT);if(label.startsWith("✓"))return "check";if(label.contains("глина")||label.contains("бумага")||label.contains("лес")||label.contains("чернила"))return "palette";if(label.contains("сохранить"))return "save";if(label.contains("отправить"))return "send";if(label.contains("обновить")||label.contains("проверк")||label.contains("проверить"))return "refresh";if(label.contains("запустить"))return "play";if(label.contains("остановить"))return "stop";if(label.contains("импорт"))return "download";if(label.contains("экспорт"))return "upload";if(label.contains("аккаунт")||label.contains("профиль")||label.contains("войти"))return "user";if(label.contains("выйти"))return "logout";if(label.contains("как работает"))return "info";if(label.contains("продажи")||label.contains("заказы"))return "chart";if(label.contains("шаблон"))return "document";if(label.contains("←"))return "back";if(label.contains("чаты"))return "chat";if(label.contains("лоты")||label.contains("категории"))return "lots";if(label.contains("журнал"))return "clock";if(label.contains("правила"))return "edit";if(label.contains("сайте")||label.contains("история"))return "external";return "settings";}
