        body.addView(action("Выбрать категории",()->run(()->{FunPayClient client=new FunPayClient(this);client.authenticate();return client.categories();},r->{@SuppressWarnings("unchecked") List<String> list=(List<String>)r;if(list.isEmpty()){alert("Категории не найдены. Проверьте лоты на сайте.");return;}JSONArray selected=prefs.config().optJSONArray("fpToolsSelectedBumpCategories");Set<String> old=new HashSet<>();if(selected!=null)for(int i=0;i<selected.length();i++)old.add(selected.optString(i));boolean[] checked=new boolean[list.size()];for(int i=0;i<list.size();i++)checked[i]=old.contains(list.get(i))||old.contains(FunPayClient.BASE+list.get(i));new AlertDialog.Builder(this).setTitle("Категории поднятия").setMultiChoiceItems(list.toArray(new String[0]),checked,(d,w,on)->checked[w]=on).setPositiveButton("Сохранить",(d,w)->{try{JSONArray a=new JSONArray();for(int i=0;i<list.size();i++)if(checked[i])a.put(FunPayClient.BASE+list.get(i));JSONObject cfg=prefs.config();cfg.put("fpToolsSelectedBumpCategories",a).put("fpToolsSelectiveBumpEnabled",true);prefs.save(cfg);}catch(Exception e){alert(e.getMessage());}}).setNegativeButton("Отмена",null).show();})));
