            LinearLayout tile=new LinearLayout(this);tile.setOrientation(LinearLayout.VERTICAL);tile.setGravity(Gravity.CENTER_VERTICAL);tile.setPadding(dp(14),dp(12),dp(14),dp(12));tile.setMinimumHeight(dp(88));tile.setTag("theme-"+id);tile.setContentDescription(Palette.NAMES[i]);tile.setSelected(selected);tile.setFocusable(true);tile.setClickable(true);
