            GridLayout.LayoutParams layout=new GridLayout.LayoutParams(GridLayout.spec(i/2),GridLayout.spec(i%2,1f));layout.width=0;layout.height=-2;layout.setMargins(i%2==0?0:dp(5),dp(5),i%2==0?dp(5):0,dp(5));grid.addView(tile,layout);
